from hypothesis import strategies as st

@st.composite
def gen(draw):
    length = draw(st.integers(1, 8))
    chars = draw(st.lists(st.sampled_from(['0', '1', '?']), min_size=length, max_size=length))
    s = ''.join(chars)
    choice = draw(st.integers(0, 3))
    if choice == 0:
        n = draw(st.integers(1, 20))
    elif choice == 1:
        n = draw(st.integers(1, 300))
    elif choice == 2:
        n = draw(st.integers(1, 10**18))
    else:
        n = 10**18
    return f"{s}\n{n}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    s, n_str = t
    if not (1 <= len(s) <= 60):
        return False
    if any(c not in '01?' for c in s):
        return False
    if not n_str.lstrip('-').isdigit():
        return False
    n = int(n_str)
    return 1 <= n <= 10**18

def ref(inp):
    t = inp.split()
    s, n = t[0], int(t[1])
    qpos = [i for i, c in enumerate(s) if c == '?']
    k = len(qpos)
    best = -1
    for mask in range(1 << k):
        arr = list(s)
        for j, p in enumerate(qpos):
            arr[p] = '1' if (mask >> j) & 1 else '0'
        val = int(''.join(arr), 2)
        if val <= n and val > best:
            best = val
    return str(best)
